let deps={};
let A={prefs:null,open:false,menu:false,tab:'menu',paused:false,orientationPause:false,engine:null,board:[],loading:false,images:{},audio:null,joystick:{},adminAtOpen:false};
const $=(q,r=document)=>r.querySelector(q), $$=(q,r=document)=>[...r.querySelectorAll(q)];
const state=()=>deps.getState?.()||{}; const icon=n=>deps.icon?deps.icon(n):n; const esc=v=>deps.esc?deps.esc(v):String(v||''); const toast=m=>deps.setToast?.(m);
const skin=id=>SKINS.find(s=>s.id===id)||SKINS[0];
const isLandscape=()=>A.prefs?.orientation==='landscape';
const orientationMatches=()=>isLandscape()?innerWidth>innerHeight:innerHeight>=innerWidth;
function init(d){deps=d;loadPrefs();preload();window.addEventListener('resize',()=>{if(A.open){renderOverlay();}});document.addEventListener('dblclick',blockZoom,{passive:false});document.addEventListener('gesturestart',blockZoom,{passive:false});document.addEventListener('touchmove',blockGameMove,{passive:false});document.addEventListener('visibilitychange',()=>{if(A.open&&document.hidden){A.paused=true;stopLoop();pauseAndStore('Paused while away.');submitScore(true).catch?.(()=>{});}});window.addEventListener('pagehide',()=>{if(A.open){A.paused=true;stopLoop();pauseAndStore('Paused while away.');submitScore(true).catch?.(()=>{});}});}
function blockGameMove(e){if(A.open&&e.target.closest?.('#zs52Root')&&!e.target.closest?.('.zs52-menu-box,.zs52-menu-skins,.zs52-menu-board'))e.preventDefault();}
function blockZoom(e){if(A.open){e.preventDefault();e.stopPropagation();}}
function loadPrefs(){const keys=['zc2-zs-prefs','zc2-zs-v56','zc2-zs-v55','zc2-zs-v54','zc2-zs-v53'];let merged={skin:'gunmetal',high:0,last:0,music:true,flip:false,codeSkins:[],orientation:'portrait'};for(const key of keys){try{const p=JSON.parse(localStorage.getItem(key)||'{}');if(Number(p.high||0)>=merged.high){merged.high=Number(p.high||0);if(p.skin)merged.skin=p.skin;}merged.last=Math.max(merged.last,Number(p.last||0));if(p.music===false)merged.music=false;if(p.flip)merged.flip=true;if(p.orientation==='landscape'||p.orientation==='portrait')merged.orientation=p.orientation;if(Array.isArray(p.codeSkins))merged.codeSkins=[...new Set([...merged.codeSkins,...p.codeSkins])];}catch{}}A.prefs={skin:merged.skin||'gunmetal',high:merged.high,last:merged.last,music:merged.music!==false,flip:!!merged.flip,orientation:merged.orientation||'portrait',codeSkins:merged.codeSkins};if(!isUnlocked(A.prefs.skin))A.prefs.skin='gunmetal';savePrefs();}
function savePrefs(){localStorage.setItem('zc2-zs-prefs',JSON.stringify(A.prefs));}
function adminUnlocked(){return !!state().admin;}
function isUnlocked(id){const s=skin(id);return id==='gunmetal'||adminUnlocked()||A.prefs.high>=s.unlock||A.prefs.codeSkins.includes(id);}
function refreshSkinCards(){const best=$('#zs52PersonalBest');if(best)best.textContent=A.prefs.high.toLocaleString();$$('[data-zs-skin],[data-skin]').forEach(b=>{const id=b.dataset.zsSkin||b.dataset.skin,s=skin(id),unlocked=isUnlocked(id),selected=A.prefs.skin===id;b.disabled=!unlocked;b.classList.toggle('locked',!unlocked);b.classList.toggle('selected',selected);b.classList.toggle('active',selected);const sm=b.querySelector('small');if(sm)sm.textContent=selected?'EQUIPPED':unlocked?'TAP TO EQUIP':s.codeOnly?'SPECIAL CODE ONLY':'UNLOCK '+s.unlock.toLocaleString();});}
function ensureImage(key,src){if(!A.images[key]){const im=new Image();im.decoding='async';im.src='./'+src;A.images[key]=im}return A.images[key];}
function preload(){Object.entries(SPRITES).forEach(([k,src])=>ensureImage(k,src));Object.entries(PICKUP_SPRITES).forEach(([k,src])=>ensureImage('pickup_'+k,src));Object.entries(BULLET_SPRITES).forEach(([k,src])=>ensureImage('bullet_'+k,src));ensureImage('map_'+MAPS[0].id,MAPS[0].img);}
const RUN_KEY='zc2-zs-run';
function pauseAndStore(msg='Run paused.'){const e=A.engine;if(!e||e.over||!e.started)return;try{localStorage.setItem(RUN_KEY,JSON.stringify({savedAt:Date.now(),orientation:A.prefs.orientation,engine:{...e,canvas:null,ctx:null,raf:0,last:0,fireHeld:false,ticker:msg||e.ticker}}));}catch(err){console.warn('pause save failed',err)}}
function clearStoredRun(){try{localStorage.removeItem(RUN_KEY)}catch{}}
function getStoredRun(){try{return JSON.parse(localStorage.getItem(RUN_KEY)||'null')}catch{return null}}
function restoreRun(){const data=getStoredRun();if(!data?.engine||data.orientation!==A.prefs.orientation)return false;newRun(false);Object.assign(A.engine,data.engine,{canvas:null,ctx:null,last:0,raf:0,fireHeld:false,transition:null});A.engine.bossesSeen=A.engine.bossesSeen||{};A.engine.bossCooldown=A.engine.bossCooldown||0;A.engine.player.fireFxUntil=0;A.engine.player.victoryUntil=0;A.engine.ticker='Run resumed';return true;}
function checkSkinUnlocks(before,after){const fresh=SKINS.filter(s=>!s.codeOnly&&s.unlock>before&&s.unlock<=after);if(fresh.length)toast(`Console skin unlocked: ${fresh.map(s=>s.name).join(', ')}`);refreshSkinCards();}
async function syncProfile(){if(!state().session)return;try{const {data}=await deps.supabase.from('arcade_profiles').select('high_score,selected_skin,unlocked_skins').eq('user_id',state().session.user.id).maybeSingle();if(!data)return;A.prefs.high=Math.max(A.prefs.high,Number(data.high_score||0));A.prefs.codeSkins=[...new Set([...(A.prefs.codeSkins||[]),...(data.unlocked_skins||[])])];if(data.selected_skin&&isUnlocked(data.selected_skin))A.prefs.skin=data.selected_skin;savePrefs();}catch(e){console.warn(e)}}
function orientationButtons(){return `<div class="zs510-orientation"><button data-zs-orient="portrait" class="${!isLandscape()?'active':''}">${icon('stay_current_portrait')}<span><b>Vertical</b><small>Joey Rob shoots up</small></span></button><button data-zs-orient="landscape" class="${isLandscape()?'active':''}">${icon('stay_current_landscape')}<span><b>Horizontal</b><small>Joey Rob shoots right</small></span></button></div>`}
function pageHtml(){const top=A.board.slice(0,8);const cards=SKINS.map(s=>{const unlocked=isUnlocked(s.id),selected=A.prefs.skin===s.id;return `<button class="zs52-skin ${unlocked?'unlocked':'locked'} ${selected?'selected':''}" data-zs-skin="${s.id}" ${unlocked?'':'disabled'}><span class="zs52-skin-preview"><img src="./${s.img}" alt="${esc(s.name)}"></span><span class="zs52-skin-copy"><b>${esc(s.name)}</b><small>${selected?'EQUIPPED':unlocked?'TAP TO EQUIP':s.codeOnly?'SPECIAL CODE ONLY':'UNLOCK '+s.unlock.toLocaleString()}</small></span></button>`}).join('');return `<section class="zs510-hub"><div class="zs510-hero"><img src="./zc2-zombie-smash-promo.png" alt="Zombie Smash"><div class="zs510-hero-copy"><span class="kicker">ZC2 ARENA</span><h1>ZOMBIE <em>SMASH</em></h1><p>Joey Rob versus Dr Mantis and the horde. Pick an orientation, lock it for the run and chase the global board.</p>${orientationButtons()}<button class="btn primary big zs510-play" id="zs52Play">${icon('sports_esports')}PLAY GAME</button><div class="zs510-quickstats"><span><b id="zs52PersonalBest">${A.prefs.high.toLocaleString()}</b><small>PERSONAL BEST</small></span><span><b>6</b><small>BOSSES</small></span><span><b>∞</b><small>FINAL WAVE</small></span></div></div></div><div class="zs510-focus-grid"><article class="panel premium-panel zs510-board" id="zs52BoardPanel"><div class="panel-head"><div><span class="kicker">LEADERBOARD</span><h2>Zombie Smash</h2></div><button id="zs52Refresh">Refresh ›</button></div><div id="zs52Board">${boardRows(top)}</div></article><article class="panel premium-panel zs510-skins"><div class="panel-head"><div><span class="kicker">CONSOLE FRAME</span><h2>Choose your skin</h2><p>Skins now decorate the outer console frame only.</p></div></div><div class="zs52-skin-grid">${cards}</div></article></div><div class="zs510-community-links"><button data-page="tournaments">${icon('emoji_events')}<span><b>Tournaments</b><small>Create, enter and run competitions</small></span></button><button data-page="community">${icon('groups')}<span><b>Community</b><small>Players, groups and notices</small></span></button></div></section>`}
function boardRows(rows){return rows?.length?rows.map((r,i)=>`<div class="rank-row"><span class="place">${r.rank||i+1}</span><span class="name">${esc(r.gamertag||'Player')}</span><span class="metric">${Number(r.high_score||0).toLocaleString()}</span><small>${esc(skin(r.selected_skin||'gunmetal').name)}</small></div>`).join(''):`<div class="empty"><div>${icon('leaderboard')}<div>No score posted yet.</div></div></div>`}
async function loadBoard(){if(A.loading)return;A.loading=true;try{let rows=[];const rpc=await deps.supabase.rpc('get_arcade_leaderboard',{p_limit:100});if(!rpc.error&&Array.isArray(rpc.data))rows=rpc.data;if(!rows.length){const {data,error}=await deps.supabase.from('arcade_profiles').select('user_id,high_score,selected_skin');if(error)throw error;const ps=state().profiles||[];rows=(data||[]).map(r=>({user_id:r.user_id,gamertag:ps.find(p=>p.id===r.user_id)?.gamertag||'Player',high_score:r.high_score||0,selected_skin:r.selected_skin||'gunmetal'})).sort((a,b)=>Number(b.high_score)-Number(a.high_score));}A.board=rows.map((r,i)=>({...r,rank:i+1}));}catch(e){console.warn('Arcade leaderboard:',e)}finally{A.loading=false;const el=$('#zs52Board');if(el)el.innerHTML=boardRows(A.board.slice(0,20));}}
function bindPage(){$('#zs52Play')?.addEventListener('click',open);$('#zs52Refresh')?.addEventListener('click',loadBoard);$$('[data-zs-orient]').forEach(b=>b.addEventListener('click',()=>{A.prefs.orientation=b.dataset.zsOrient;savePrefs();$$('[data-zs-orient]').forEach(x=>x.classList.toggle('active',x.dataset.zsOrient===A.prefs.orientation));}));$$('[data-zs-skin]').forEach(b=>b.addEventListener('click',()=>selectSkin(b.dataset.zsSkin)));syncProfile().then(refreshSkinCards);loadBoard();}
async function open(){await syncProfile();A.adminAtOpen=adminUnlocked();A.open=true;A.menu=false;A.paused=false;document.documentElement.classList.add('zs52-locked');document.body.classList.add('zs52-playing');try{await screen.orientation?.lock?.(isLandscape()?'landscape':'portrait')}catch{}try{if(!document.fullscreenElement&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen()}catch{}if(!restoreRun())newRun();renderOverlay();if(A.engine?.started)startLoop();}
function close(saveProgress=true){if(saveProgress&&A.engine&&!A.engine.over&&A.engine.started){pauseAndStore('Run paused - tap Play to resume.');submitScore(true).catch?.(()=>{});}else if(!saveProgress)clearStoredRun();stop();A.open=false;A.menu=false;document.documentElement.classList.remove('zs52-locked');document.body.classList.remove('zs52-playing');try{screen.orientation?.unlock?.()}catch{}try{if(document.fullscreenElement)document.exitFullscreen?.()}catch{}$('#zs52Root')?.remove();refreshSkinCards();}
function newRun(clear=true){if(clear)clearStoredRun();A.engine={canvas:null,ctx:null,w:0,h:0,last:0,raf:0,started:false,over:false,elapsed:0,wave:1,mapIndex:0,mapBanner:2.0,between:0,waveTarget:waveCount(1),waveSpawned:0,waveResolved:0,spawnTimer:.5,pickupTimer:24,formationTimer:25,scoreSyncTimer:25,lastFormation:'',breaches:0,breachLimit:10,score:0,kills:0,slowUntil:0,speedUntil:0,rapidUntil:0,shieldUntil:0,ticker:isLandscape()?'Press UP, DOWN or FIRE to start':'Press LEFT, RIGHT or FIRE to start',bullets:[],zombies:[],pickups:[],bossProjectiles:[],player:{x:0,y:0,r:21,lives:5,maxLives:5,inv:0,move:{x:0,y:0},gun:'pistol',ammo:Infinity,cool:0,fireFxUntil:0,victoryUntil:0},fireHeld:false,cheated:false,cheats:{dmr:false,tenLives:false},infinite:false,bossesSeen:{},bossCooldown:0,bossMusicUntil:0,transition:null,pendingBoss:null};}
function renderOverlay(){let r=$('#zs52Root');if(!r){r=document.createElement('div');r.id='zs52Root';document.body.appendChild(r)}if(!orientationMatches()){A.orientationPause=true;stopLoop();r.innerHTML=`<div class="zs52-overlay"><div class="zs52-orient-warning"><img src="./community-arena-emblem.png" alt=""><span class="kicker">ORIENTATION LOCKED</span><h2>${isLandscape()?'Rotate to landscape':'Rotate upright'}</h2><p>This run is locked to ${isLandscape()?'horizontal right-fire':'vertical up-fire'} play. Rotate the device to continue.</p><button class="btn primary big" id="zs52RotateExit">Exit game</button></div></div>`;$('#zs52RotateExit').onclick=()=>close(true);return}const resumeFromOrientation=A.orientationPause;A.orientationPause=false;r.innerHTML=consoleHtml();bindOverlay();resizeCanvas();draw();hud();if(resumeFromOrientation&&A.engine?.started&&!A.paused&&!A.menu)setTimeout(startLoop,0);}
function consoleHtml(){const s=skin(A.prefs.skin),mode=isLandscape()?'landscape':'portrait';const move=isLandscape()?`<div class="zs52-dpad" aria-label="Move"><button data-dir="up" class="up" aria-label="Move up"></button><button data-dir="down" class="down" aria-label="Move down"></button></div>`:`<div class="zs52-portrait-move" aria-label="Move"><button data-dir="left" class="zs52-lrbtn left" aria-label="Move left"></button><button data-dir="right" class="zs52-lrbtn right" aria-label="Move right"></button></div>`;return `<div class="zs52-overlay"><div class="zs52-shell mode-${mode} skin-${s.id}" style="--skin-art:url('./${s.img}');--skin-accent:${s.accent}"><div class="zs52-skinwash"></div><div class="zs52-screen"><div class="zs52-hudtop"><span><small>WAVE</small><b id="zs52Wave">1</b></span><span><small>ZOMBIES</small><b id="zs52Remaining">0</b></span><span><small>SCORE</small><b id="zs52Score">0</b></span><span><small>BASE</small><b id="zs52Base">0/10</b></span></div><canvas id="zs52Canvas"></canvas><div class="zs52-hudbottom"><div id="zs52Lives" class="zs52-lives"></div><div><small>WEAPON</small><b id="zs52Gun">PISTOL</b><span id="zs52Ammo">∞</span></div><div><small>GROUND</small><b id="zs52Map">CONCRETE</b></div></div></div><button class="zs52-topbtn menu" id="zs52Menu" aria-label="Menu">${icon('menu')}</button><button class="zs52-topbtn pause" id="zs52Pause" aria-label="Pause">${icon('pause')}</button><div class="zs52-move-zone ${A.prefs.flip?'flipped':''}">${move}</div><button class="zs52-fire ${A.prefs.flip?'flipped':''}" id="zs52Fire" aria-label="Fire"><span>FIRE</span></button><div class="zs52-ticker" id="zs52Ticker">${esc(A.engine?.ticker||'')}</div>${A.menu?menuHtml():''}</div></div>`}
function menuHtml(){const skins=SKINS.map(s=>`<button class="zs52-menu-skin ${isUnlocked(s.id)?'':'locked'} ${A.prefs.skin===s.id?'active':''}" data-skin="${s.id}" ${isUnlocked(s.id)?'':'disabled'}><img src="./${s.img}" alt=""><span><b>${esc(s.name)}</b><small>${A.prefs.skin===s.id?'EQUIPPED':isUnlocked(s.id)?'UNLOCKED':s.codeOnly?'SPECIAL CODE ONLY':'Unlock '+s.unlock.toLocaleString()}</small></span></button>`).join('');let body='';if(A.tab==='instructions')body=`<div class="zs52-instructions"><article><b>${isLandscape()?'Horizontal mode':'Vertical mode'}</b><span>${isLandscape()?'Zombies advance right-to-left. Joey Rob stays on the left defence line and fires right.':'Zombies advance top-to-bottom. Joey Rob stays on the bottom defence line and fires up.'}</span></article><article><b>Bosses</b><span>Bosses only appear between waves, never mid-fight. Clear a wave, the lights go out, and they arrive already on screen. Each has its own attacks that change per stage - watch their tells and dodge.</span></article><article><b>Power-ups</b><span>Pickups are rare and land on your movement line.</span></article></div>`;else if(A.tab==='leaderboard')body=`<div class="zs52-menu-board">${boardRows(A.board.slice(0,25))}</div>`;else if(A.tab==='skins')body=`<div class="zs52-code"><input id="zs52SkinCode" maxlength="4" inputmode="numeric" placeholder="4-digit skin code"><button class="btn primary" id="zs52Redeem">Unlock</button></div><div class="zs52-menu-skins">${skins}</div>`;else body=`<div class="zs52-menu-actions"><button class="btn primary big" id="zs52Resume">${icon('play_arrow')}Resume</button><button class="btn secondary big" id="zs52Flip">${icon('swap_horiz')}Swap controls: ${A.prefs.flip?'ON':'OFF'}</button><button class="btn secondary big" id="zs52Music">${icon(A.prefs.music?'volume_up':'volume_off')}Sound: ${A.prefs.music?'ON':'OFF'}</button><button class="btn danger big" id="zs52Quit">${icon('logout')}Exit to app</button></div>`;return `<div class="zs52-menu-layer"><div class="zs52-menu-box"><header><div><span class="kicker">ZC2 ARENA</span><h2>Zombie Smash</h2></div><button id="zs52MenuClose">${icon('close')}</button></header><nav>${['menu','instructions','leaderboard','skins'].map(t=>`<button data-tab="${t}" class="${A.tab===t?'active':''}">${t}</button>`).join('')}</nav>${body}</div></div>`}
